        s4[g]=s[g];
    }
	for(i=0;i<n-m+1;i++){
	    for(j=0;j<m;j++){
	        if(s[i+j]==t[j]){
	            if(j==m-1){
	                for(u=i;u<i+k;u++){
	                    s4[u+(k-m)*f]=w[u-i];
